                    "type": "object",
                    "properties": {
                        "links": {
                            "type": "object",
                            "properties": {
                                "self": {
                                    "type": "string"
                                },
                                "related": {
                                    "type": "string"
                                }
                            },
                            "additionalProperties": false
                        },
                        "data": {
                            "oneOf": [
                                {
                                    "type": "object",
                                    "description": "The id and type form a pointer into the 'included' top level document property",
                                    "properties": {
                                        "id": {
